CREATE DATABASE IF NOT EXISTS kodelio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kodelio;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',email_verified_at DATETIME NULL,active_path_id INT UNSIGNED NULL,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE email_verifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE learning_paths(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,description TEXT,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE modules(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,path_id INT UNSIGNED NOT NULL,slug VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,description TEXT,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE CASCADE);
CREATE TABLE levels(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id INT UNSIGNED NOT NULL,level_no TINYINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,summary VARCHAR(255),pass_score TINYINT UNSIGNED NOT NULL DEFAULT 70,sort_order INT NOT NULL DEFAULT 0,UNIQUE(module_id,level_no),FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE CASCADE);
CREATE TABLE lessons(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,level_id INT UNSIGNED NOT NULL,step_no TINYINT UNSIGNED NOT NULL,type ENUM('learn','understand','practice','minigame','quiz') NOT NULL,title VARCHAR(160) NOT NULL,content MEDIUMTEXT NULL,starter_code TEXT NULL,xp_reward SMALLINT UNSIGNED NOT NULL DEFAULT 10,UNIQUE(level_id,step_no),FOREIGN KEY(level_id) REFERENCES levels(id) ON DELETE CASCADE);
CREATE TABLE lesson_progress(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id INT UNSIGNED NOT NULL,status ENUM('in_progress','completed') NOT NULL DEFAULT 'in_progress',time_spent_sec INT UNSIGNED NOT NULL DEFAULT 0,started_at DATETIME DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,UNIQUE(user_id,lesson_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE questions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lesson_id INT UNSIGNED NOT NULL,type ENUM('multiple_choice','code') NOT NULL DEFAULT 'multiple_choice',prompt TEXT NOT NULL,code_example TEXT NULL,explanation TEXT NULL,feedback_correct TEXT NULL,feedback_wrong TEXT NULL,hint TEXT NULL,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE answers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id INT UNSIGNED NOT NULL,answer_text TEXT NOT NULL,is_correct TINYINT(1) NOT NULL DEFAULT 0,feedback TEXT NULL,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE quiz_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id INT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,passed TINYINT(1) NOT NULL,wrong_details JSON NULL,taken_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE game_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id INT UNSIGNED NOT NULL,game_type ENUM('code_arrangement','find_the_bug','guess_the_output','match_the_code','quick_quiz') NOT NULL,score TINYINT UNSIGNED NOT NULL,xp_earned SMALLINT UNSIGNED NOT NULL DEFAULT 0,details JSON NULL,played_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE user_points(user_id BIGINT UNSIGNED PRIMARY KEY,xp INT UNSIGNED NOT NULL DEFAULT 0,level INT UNSIGNED NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE user_streaks(user_id BIGINT UNSIGNED PRIMARY KEY,current_streak INT UNSIGNED NOT NULL DEFAULT 0,longest_streak INT UNSIGNED NOT NULL DEFAULT 0,last_activity_date DATE NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE achievements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,description VARCHAR(255),icon VARCHAR(40) DEFAULT 'bi-trophy',xp_bonus SMALLINT UNSIGNED NOT NULL DEFAULT 0);
CREATE TABLE user_achievements(user_id BIGINT UNSIGNED NOT NULL,achievement_id INT UNSIGNED NOT NULL,earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,achievement_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(achievement_id) REFERENCES achievements(id) ON DELETE CASCADE);
CREATE TABLE daily_challenges(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,challenge_date DATE NOT NULL UNIQUE,title VARCHAR(120) NOT NULL,description TEXT,question_id INT UNSIGNED NULL,xp_reward SMALLINT UNSIGNED NOT NULL DEFAULT 20,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE SET NULL);
CREATE TABLE challenge_progress(user_id BIGINT UNSIGNED NOT NULL,challenge_id INT UNSIGNED NOT NULL,xp_earned SMALLINT UNSIGNED NOT NULL DEFAULT 0,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,challenge_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(challenge_id) REFERENCES daily_challenges(id) ON DELETE CASCADE);
CREATE TABLE placement_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,recommended_path_id INT UNSIGNED NULL,answers JSON NULL,taken_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recommended_path_id) REFERENCES learning_paths(id) ON DELETE SET NULL);
CREATE TABLE final_projects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,path_id INT UNSIGNED NOT NULL UNIQUE,title VARCHAR(160) NOT NULL,description TEXT,requirements TEXT,instructions TEXT,FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE CASCADE);
CREATE TABLE project_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,project_id INT UNSIGNED NOT NULL,link_url VARCHAR(500) NOT NULL,notes TEXT,status ENUM('submitted','reviewed','revision') NOT NULL DEFAULT 'submitted',score TINYINT UNSIGNED NULL,admin_feedback TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,UNIQUE(user_id,project_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(project_id) REFERENCES final_projects(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
ALTER TABLE users ADD FOREIGN KEY(active_path_id) REFERENCES learning_paths(id) ON DELETE SET NULL;
SET FOREIGN_KEY_CHECKS=1;
